from html.parser import HTMLParser
class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.tags = []
    def handle_starttag(self, tag, attrs):
        if tag not in ['br','hr','img','input','meta','link']:
            self.tags.append(tag)
    def handle_endtag(self, tag):
        if tag not in ['br','hr','img','input','meta','link']:
            if self.tags and self.tags[-1] == tag:
                self.tags.pop()

with open('/app/output/final_report.html', 'r') as f:
    content = f.read()
v = Validator()
v.feed(content)
print(f'HTML file size: {len(content):,} bytes')
print(f'Contains DOCTYPE: {\"<!DOCTYPE html>\" in content}')
print(f'Contains closing html: {\"</html>\" in content}')
print(f'Starts with DOCTYPE: {content[:15]}')

# Check all sections present
sections = ['Executive Summary', 'Sales Trends', 'Product', 'Store', 'Discount Impact', 'Customer Behavior']
for s in sections:
    if s in content:
        print(f'  ✓ Section found: {s}')
    else:
        print(f'  ✗ Section MISSING: {s}')

# Count embedded images
img_count = content.count('data:image/png;base64,')
print(f'Embedded charts: {img_count}')

# Check KPIs
for kpi in ['Total Revenue', 'Total Profit', 'Average Profit Margin', 'Average Order Value', 'Discount Utilization']:
    if kpi in content:
        print(f'  ✓ KPI found: {kpi}')
    else:
        print(f'  ✗ KPI MISSING: {kpi}')
"

